SELECT 

WHERE we.workation_id = #{workationId}

ORDER BY we.spent_at DESC, we.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM workation_expenses we
 WHERE we.workation_id = #{workationId}

SELECT
    COUNT(*)                    AS total_count,
    COALESCE(SUM(we.amount), 0) AS total_amount,
    (
        SELECT COALESCE(SUM(CASE WHEN is_auto_categorized = 1 THEN 1 ELSE 0 END), 0)
          FROM workation_expenses
         WHERE workation_id = #{workationId}
    )                           AS unchecked_count
  FROM workation_expenses we
 WHERE we.workation_id = #{workationId}

SELECT 

JOIN workations w
  ON w.id = we.workation_id
 AND w.user_id = #{userId}
WHERE we.id = #{expenseId}

